mapper.select:
SELECT * FROM fin_commission

     AND policy_no LIKE CONCAT('%', #{policyNo}, '%')
     AND company_id = #{companyId}
     AND direction = #{direction}
     AND status = #{status}

ORDER BY create_time DESC

SELECT direction, COUNT(*) AS count, SUM(commission_amount) AS totalAmount
FROM fin_commission
WHERE policy_date BETWEEN #{startDate} AND #{endDate}
  AND direction = #{direction}
GROUP BY direction

mapper.update:
UPDATE fin_commission
SET status = #{status}, settle_date = #{settleDate}, receipt_id = #{receiptId}, payment_id = #{paymentId}, update_by = #{updateBy}, update_time = NOW()
WHERE id = #{id}
